B.Jd=s(["\u041f\u043e\u0440\u044f\u0434\u043e\u043a \u2014 \u043f\u043e \u0443\u0433\u0440\u043e\u0437\u0435 \u0436\u0438\u0437\u043d\u0438, \u043d\u0435 \u043f\u043e \u043f\u043e\u0440\u044f\u0434\u043a\u0443 \u0443\u043f\u0430\u043a\u043e\u0432\u043a\u0438:","1. \u0416\u0433\u0443\u0442/\u0442\u0443\u0440\u043d\u0438\u043a\u0435\u0442 \u2014 \u043a\u0440\u043e\u0432\u043e\u0442\u0435\u0447\u0435\u043d\u0438\u0435 \u0438\u0437 \u043a\u043e\u043d\u0435\u0447\u043d\u043e\u0441\u0442\u0438: \u0432\u044b\u0448\u0435 \u0440\u0430\u043d\u044b, \u0442\u0443\u0433\u043e, \u043d\u0435 \u043d\u0430 \u0441\u0443\u0441\u0442\u0430\u0432, \u0434\u043e \u043e\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0438. \u0412\u0440\u0435\u043c\u044f \u2014 \u043d\u0430 \u0436\u0433\u0443\u0442.","1\u0430. \u041d\u0410\u041f\u041e\u041c\u0418\u041d\u0410\u041b\u041a\u0410: \u0437\u0430\u043f\u0438\u0448\u0438 \u0432\u0440\u0435\u043c\u044f \u043d\u0430\u043b\u043e\u0436\u0435\u043d\u0438\u044f \u0441\u0440\u0430\u0437\u0443 \u2014 \u043d\u0430 \u0436\u0433\u0443\u0442\u0435, \u043d\u0430 \u0449\u0435\u043a\u0435 \u0438\u043b\u0438 \u0448\u0435\u0435 \u0440\u0430\u043d\u0435\u043d\u043e\u0433\u043e (24-\u0447\u0430\u0441\u043e\u0432\u043e\u0439 \u0444\u043e\u0440\u043c\u0430\u0442). \u0411\u0435\u0437 \u0432\u0440\u0435\u043c\u0435\u043d\u0438 \u043d\u0435\u0432\u043e\u0437\u043c\u043e\u0436\u043d\u044b \u043a\u043e\u043d\u0432\u0435\u0440\u0441\u0438\u044f \u0438 \u0434\u043e\u043a\u043b\u0430\u0434.","2. \u041e\u043a\u043a\u043b\u044e\u0437\u0438\u043e\u043d\u043d\u0430\u044f \u043d\u0430\u043a\u043b\u0435\u0439\u043a\u0430 \u2014 \u0441\u043e\u0441\u0443\u0449\u0430\u044f \u0440\u0430\u043d\u0430 \u0433\u0440\u0443\u0434\u0438: \u0437\u0430\u043a\u0440\u044b\u0442\u044c \u0433\u0435\u0440\u043c\u0435\u0442\u0438\u0447\u043d\u043e (\u043d\u0430 \u0432\u044b\u0434\u043e\u0445\u0435). \u0421\u0442\u0430\u043b\u043e \u0445\u0443\u0436\u0435 \u0434\u044b\u0448\u0430\u0442\u044c \u2014 \u043f\u0440\u0438\u043e\u0442\u043a\u0440\u043e\u0439 \u043d\u0430 \u0441\u0435\u043a\u0443\u043d\u0434\u0443.","3. \u0413\u0435\u043c\u043e\u0441\u0442\u0430\u0442\u0438\u043a/\u0442\u0430\u043c\u043f\u043e\u043d\u0430\u0434\u0430 \u2014 \u0441\u0438\u043b\u044c\u043d\u043e\u0435 \u043a\u0440\u043e\u0432\u043e\u0442\u0435\u0447\u0435\u043d\u0438\u0435 \u0442\u0430\u043c, \u0433\u0434\u0435 \u0436\u0433\u0443\u0442 \u043d\u0435 \u043b\u043e\u0436\u0438\u0442\u0441\u044f (\u043f\u0430\u0445, \u043f\u043e\u0434\u043c\u044b\u0448\u043a\u0430): \u0437\u0430\u043f\u043e\u043b\u043d\u0438\u0442\u044c \u0440\u0430\u043d\u0443, \u0434\u0430\u0432\u0438\u0442\u044c \u043d\u0435 \u043e\u0442\u0440\u044b\u0432\u0430\u044f, \u043f\u043e\u0432\u0435\u0440\u0445 \u2014 \u0434\u0430\u0432\u044f\u0449\u0430\u044f \u043f\u043e\u0432\u044f\u0437\u043a\u0430.","4. \u0411\u0438\u043d\u0442/\u043f\u043e\u0432\u044f\u0437\u043a\u0430 \u2014 \u0437\u0430\u043a\u0440\u044b\u0442\u044c \u0440\u0430\u043d\u0443. \u0418\u043d\u043e\u0440\u043e\u0434\u043d\u043e\u0435 \u0442\u0435\u043b\u043e \u043d\u0435 \u0432\u044b\u043d\u0438\u043c\u0430\u0442\u044c.","5. \u0422\u0435\u043f\u043b\u043e-\u043e\u0434\u0435\u044f\u043b\u043e \u2014 \u043f\u043e\u0432\u0435\u0440\u0445 \u043e\u0434\u0435\u0436\u0434\u044b, \u0438\u0437\u043e\u043b\u0438\u0440\u043e\u0432\u0430\u0442\u044c \u043e\u0442 \u0437\u0435\u043c\u043b\u0438.","6. \u0410\u043d\u0442\u0438\u0431\u0438\u043e\u0442\u0438\u043a \u0438\u0437 \u0430\u043f\u0442\u0435\u0447\u043a\u0438 \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u043e \u0432\u043a\u043b\u0430\u0434\u044b\u0448\u0443 \u0441\u0432\u043e\u0435\u0433\u043e \u043f\u0440\u0435\u043f\u0430\u0440\u0430\u0442\u0430 \u0438 \u043f\u0440\u0438\u043a\u0430\u0437\u0443; \u0441\u0430\u043c\u043e\u0441\u0442\u043e\u044f\u0442\u0435\u043b\u044c\u043d\u044b\u0439 \u043f\u043e\u0434\u0431\u043e\u0440 \u0437\u0430\u043f\u0440\u0435\u0449\u0451\u043d.","\u0421\u043e\u0441\u0442\u0430\u0432 \u0438 \u0441\u0440\u043e\u043a\u0438 \u0441\u0432\u0435\u0440\u044f\u0439 \u0441 \u0432\u043a\u043b\u0430\u0434\u044b\u0448\u0435\u043c \u0421\u0412\u041e\u0415\u0419 \u0430\u043f\u0442\u0435\u0447\u043a\u0438 \u2014 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u043d\u0435 \u0437\u0430\u043c\u0435\u043d\u044f\u0435\u0442 \u0441\u043e\u0434\u0435\u0440\u0436\u0438\u043c\u043e\u0435."],t.s)
B.RE=new A.bk("IVA","\u0418\u043d\u0434\u0438\u0432\u0438\u0434\u0443\u0430\u043b\u044c\u043d\u0430\u044f \u0430\u043f\u0442\u0435\u0447\u043a\u0430: \u043f\u043e\u0440\u044f\u0434\u043e\u043a \u043f\u0440\u0438\u043c\u0435\u043d\u0435\u043d\u0438\u044f",0,B.Jd,"5 \u041c\u0413 \u041a\u0413\u0412 (\u0430\u043b\u0433\u043e\u0440\u0438\u0442\u043c \u041a\u0423\u041b\u0410\u041a/\u0411\u0410\u0420\u0418\u041d, \u0441\u043d\u0435\u043f\u0448\u043e\u0442 \u043a\u0430\u043d\u0430\u043b\u0430); \u0423\u0426\u0422\u041c \xab\u0421\u0432\u0430\u0440\u043e\u0433\xbb (\u0442\u0430\u043c\u043f\u043e\u043d\u0430\u0434\u0430 \u0433\u0435\u043c\u043e\u0441\u0442\u0430\u0442\u0438\u043a\u043e\u043c); \u043a\u0430\u0440\u0442\u043e\u0447\u043a\u0430 \u0441\u0430\u043c\u043e\u043f\u043e\u043c\u043e\u0449\u0438 \u0432\u043b\u0430\u0434\u0435\u043b\u044c\u0446\u0430","\u0441\u043e\u0441\u0442\u0430\u0432 \u0441\u0432\u0435\u0440\u044f\u0442\u044c \u0441 \u0432\u043a\u043b\u0430\u0434\u044b\u0448\u0435\u043c")
B.Jq=s(["\u041f\u043e\u0434 \u043e\u0433\u043d\u0451\u043c: \u0442\u043e\u043b\u044c\u043a\u043e 10-\u0441\u0435\u043a\u0443\u043d\u0434\u043d\u044b\u0435 \u0432\u043c\u0435\u0448\u0430\u0442\u0435\u043b\u044c\u0441\u0442\u0432\u0430 (\u0436\u0433\u0443\u0442, \u0433\u0435\u0440\u043c\u0435\u0442\u0438\u0437\u0430\u0446\u0438\u044f \u0433\u0440\u0443\u0434\u0438, \u043f\u043e\u0437\u0430) \u2192 \u0443\u043a\u0440\u044b\u0442\u0438\u0435 \u2192 \u0434\u0432\u0438\u0436\u0435\u043d\u0438\u0435 \u0432\u0430\u0436\u043d\u0435\u0435.","\u0420\u0430\u043d\u0435\u043d\u044b\u0439 \u0442\u043e\u0432\u0430\u0440\u0438\u0449, \u0432\u044b\u043d\u0435\u0441\u0442\u0438 \u043d\u0435\u043b\u044c\u0437\u044f: \u043f\u0440\u0435-\u0431\u0440\u0438\u0444 \u0440\u0430\u043d\u0435\u043d\u043e\u043c\u0443 \u2192 \u0447\u0435\u043a-\u043b\u0438\u0441\u0442 \u0431\u0440\u043e\u0441\u0430\u043d\u0438\u044f \u2192 \u043e\u0442\u0445\u043e\u0434 (\u043d\u0435 \u043a\u0443\u0447\u043a\u043e\u0432\u0430\u0442\u044c\u0441\u044f, \u043d\u0435 \u0432\u043e\u0437\u0432\u0440\u0430\u0449\u0430\u0442\u044c\u0441\u044f \u0441\u0440\u0430\u0437\u0443) \u2192 \u0432\u043e\u0437\u0432\u0440\u0430\u0442 \u043f\u043e\u0441\u043b\u0435 \u043e\u0442\u0431\u043e\u044f \u2192 \u043f\u043e\u0432\u0442\u043e\u0440\u043d\u0430\u044f \u0441\u043e\u0440\u0442\u0438\u0440\u043e\u0432\u043a\u0430.","\u0422\u044b \u0440\u0430\u043d\u0435\u043d, \u0433\u0440\u0443\u043f\u043f\u0430 \u043e\u0442\u043e\u0448\u043b\u0430: \u043a\u0430\u0440\u0442\u043e\u0447\u043a\u0430 \u0441\u0430\u043c\u043e\u043f\u043e\u043c\u043e\u0449\u0438 \u2014 \u0441\u0432\u0435\u0440\u0445\u0443 \u0432\u043d\u0438\u0437, [\u0414\u0420\u041e\u041d] \u2192 [\u041a\u0420\u041e\u0412\u042c] \u2192 [\u0413\u0420\u0423\u0414\u042c] \u2192 [\u041f\u041e\u0417\u0410] \u2192 [\u0422\u0415\u041f\u041b\u041e] \u2192 [\u041c\u0415\u0422\u041a\u0410/\u0421\u0412\u042f\u0417\u042c].","\u041d\u0438\u043a\u043e\u0433\u0434\u0430: \u043d\u0435 \u0441\u043d\u0438\u043c\u0430\u0442\u044c \u0436\u0433\u0443\u0442, \u043d\u0435 \u0432\u044b\u043d\u0438\u043c\u0430\u0442\u044c \u0438\u043d\u043e\u0440\u043e\u0434\u043d\u043e\u0435, \u043d\u0435 \u0434\u0430\u0432\u0430\u0442\u044c \u043f\u0440\u0435\u043f\u0430\u0440\u0430\u0442\u043e\u0432 \u0431\u0435\u0437 \u043c\u0435\u0434\u0440\u0430\u0431\u043e\u0442\u043d\u0438\u043a\u0430, \u043d\u0435 \u0431\u0435\u0433\u0430\u0442\u044c \u043f\u043e \u043e\u0442\u043a\u0440\u044b\u0442\u043e\u043c\u0443 \u043f\u043e\u0434 \u0434\u0440\u043e\u043d\u043e\u043c."],t.s)
